def conn():
    c=sqlite3.connect(DB_PATH); c.row_factory=sqlite3.Row; return c

def init_db():
    c=conn()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS services(
      id INTEGER PRIMARY KEY AUTOINCREMENT,name_en TEXT NOT NULL,name_kn TEXT NOT NULL,category TEXT NOT NULL,department TEXT,
      description_en TEXT,description_kn TEXT,keywords TEXT,application_url TEXT,status_url TEXT,official_url TEXT,
      documents_en TEXT,steps_en TEXT,eligibility_en TEXT,helpline TEXT,verified_on TEXT DEFAULT '2026-09-07',
      fees_en TEXT DEFAULT 'Check the official portal for current applicable fees.',processing_time_en TEXT DEFAULT 'Varies by service and department.',location TEXT DEFAULT 'Karnataka',online_available INTEGER DEFAULT 1
    );
    CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,role TEXT DEFAULT 'user',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE IF NOT EXISTS search_history(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,query TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE IF NOT EXISTS activity_history(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,details TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE IF NOT EXISTS applications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,service_id INTEGER,reference TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE IF NOT EXISTS saved_services(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,service_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,service_id));
    CREATE TABLE IF NOT EXISTS feedback(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,service_id INTEGER,rating INTEGER,comment TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
    """)
    # Safe migrations for existing databases
    existing=[r['name'] for r in c.execute('PRAGMA table_info(services)').fetchall()]
    for col,typ,default in [('fees_en','TEXT',"'Check the official portal for current applicable fees.'"),('processing_time_en','TEXT',"'Varies by service and department.'"),('location','TEXT',"'Karnataka'"),('online_available','INTEGER','1')]:
      if col not in existing: c.execute(f'ALTER TABLE services ADD COLUMN {col} {typ} DEFAULT {default}')
    ucols=[r['name'] for r in c.execute('PRAGMA table_info(users)').fetchall()]
    if 'role' not in ucols: c.execute("ALTER TABLE users ADD COLUMN role TEXT DEFAULT 'user'")
    c.execute("CREATE TABLE IF NOT EXISTS feedback(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,service_id INTEGER,rating INTEGER,comment TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP)")
    # Demo administrator for the final-year project dashboard
    if not c.execute("SELECT 1 FROM users WHERE email='admin@nammasahaya.local'").fetchone():
      salt=secrets.token_hex(16); h=hashlib.pbkdf2_hmac('sha256','Admin@12345'.encode(),salt.encode(),120000).hex()
      c.execute("INSERT INTO users(name,email,password_hash,password_salt,role) VALUES(?,?,?,?,?)",('NammaSahaya Admin','admin@nammasahaya.local',h,salt,'admin'))
    count=c.execute('SELECT COUNT(*) n FROM services').fetchone()['n']
    if count==0:
      for s in SERVICES_DATA:
        c.execute('INSERT INTO services(name_en,name_kn,category,department,description_en,description_kn,keywords,application_url,status_url,official_url,documents_en,steps_en,eligibility_en,helpline) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)',s)

